import pandas as pd


def calculate_total_sales(df):
    """Calculate total revenue."""
    return df["Revenue"].sum()


def calculate_average_sales(df):
    """Calculate average revenue."""
    return df["Revenue"].mean()


def calculate_total_quantity(df):
    """Calculate total quantity sold."""
    return df["Quantity"].sum()


def product_sales(df):
    """Calculate revenue generated by each product."""
    return (
        df.groupby("Product")["Revenue"]
        .sum()
        .sort_values(ascending=False)
    )


def product_quantity(df):
    """Calculate quantity sold for each product."""
    return (
        df.groupby("Product")["Quantity"]
        .sum()
        .sort_values(ascending=False)
    )


def daily_sales(df):
    """Calculate daily revenue."""
    return df.groupby("Date")["Revenue"].sum()


def highest_revenue_product(df):
    """Find the product with the highest revenue."""
    sales = product_sales(df)
    return sales.idxmax(), sales.max()


def lowest_revenue_product(df):
    """Find the product with the lowest revenue."""
    sales = product_sales(df)
    return sales.idxmin(), sales.min()


def highest_sales_date(df):
    """Find the date with the highest revenue."""
    sales = daily_sales(df)
    return sales.idxmax(), sales.max()


def generate_summary(df):
    """Generate a basic sales summary."""

    total_sales = calculate_total_sales(df)
    average_sales = calculate_average_sales(df)
    total_quantity = calculate_total_quantity(df)

    highest_product, highest_product_revenue = (
        highest_revenue_product(df)
    )

    lowest_product, lowest_product_revenue = (
        lowest_revenue_product(df)
    )

    best_date, best_date_revenue = highest_sales_date(df)

    summary = {
        "Total Revenue": total_sales,
        "Average Revenue": average_sales,
        "Total Quantity Sold": total_quantity,
        "Highest Revenue Product": highest_product,
        "Highest Product Revenue": highest_product_revenue,
        "Lowest Revenue Product": lowest_product,
        "Lowest Product Revenue": lowest_product_revenue,
        "Best Sales Date": best_date,
        "Best Date Revenue": best_date_revenue,
    }

    return summary